<script setup lang="ts">
import { computed, onMounted, shallowRef } from 'vue'
import { useLibrary } from '@/composables/useLibrary'
import MediaCatalog from './MediaCatalog.vue'
import MovieInspector from './MovieInspector.vue'
const props = defineProps<{ csrfToken: string; username: string; labels: Record<string, string> }>()
const emit = defineEmits<{ toggleLocale: [] }>()
const sourceName = shallowRef('Movies'); const sourcePath = shallowRef('/media/movies'); const query = shallowRef('')
const selectedID = shallowRef<number | null>(null)
const { sourceItems, mediaItems, jobItems, error, hasSources, refresh, createSource, scan: queueScan } = useLibrary(() => props.csrfToken)
const activeJobs = computed(() => jobItems.value.filter(job => job.state === 'queued' || job.state === 'running'))
async function add() { await createSource(sourceName.value, sourcePath.value) }
async function scan(id: number) { await queueScan(id) }
async function search(value = '') { query.value = value; await refresh(query.value) }
onMounted(refresh)
</script>
<template><main class="library-workspace"><header class="library-header"><div><p class="eyebrow">MediaGrap · library desk</p><h1>{{ labels.library }}</h1><p>{{ props.username }}</p></div><div class="header-actions"><button type="button" @click="emit('toggleLocale')">{{ labels.language }}</button><button type="button" @click="refresh(query)">{{ labels.refresh }}</button></div></header><p v-if="error" class="library-error">{{ error }}</p><section v-if="!hasSources" class="source-onboarding"><p class="eyebrow">{{ labels.source }}</p><h2>{{ labels.firstSource }}</h2><form @submit.prevent="add"><label>Name<input v-model="sourceName" required /></label><label>{{ labels.containerPath }}<input v-model="sourcePath" required /></label><button type="submit">{{ labels.addSource }}</button></form></section><template v-else><section class="source-strip"><article v-for="source in sourceItems" :key="source.id"><p>{{ source.name }}</p><strong>{{ source.itemCount }} films</strong><small>{{ source.rootPath }}</small><button type="button" @click="scan(source.id)">{{ labels.scan }}</button></article></section><section class="library-desk" :class="{ 'is-mobile-detail': selectedID !== null }"><MediaCatalog :items="mediaItems" :selected-id="selectedID" :active-job="activeJobs[0]" :labels="labels" @search="search" @select="selectedID = $event"/><MovieInspector :item-id="selectedID" :csrf-token="csrfToken" :labels="labels" @close="selectedID = null" /></section></template></main></template>
<style scoped>.library-workspace{max-width:88rem;margin:auto;padding:clamp(1.25rem,3vw,3rem)}.library-header{display:flex;justify-content:space-between;gap:1rem;align-items:end;padding-bottom:1.6rem;border-bottom:1px solid var(--mist-300)}.library-header h1{margin:.35rem 0;font:500 clamp(2.5rem,6vw,5rem)/.9 var(--font-display);letter-spacing:-.07em}.library-header p{color:var(--ink-600)}.header-actions{display:flex;gap:.5rem}.header-actions button,.source-strip button,.source-onboarding button{min-height:2.6rem;padding:.5rem .8rem;border:1px solid var(--ink-700);border-radius:.45rem;background:var(--ink-900);color:white;font-weight:700;cursor:pointer}.source-onboarding{margin-top:2rem;padding:clamp(1.2rem,3vw,2.4rem);border:1px solid var(--mist-300);border-radius:1rem;background:var(--paper)}h2{margin:.35rem 0;font:500 2rem var(--font-display)}form{display:grid;gap:.8rem;margin-top:1.3rem}label{display:grid;gap:.3rem;font-size:.8rem;font-weight:700}input{min-height:2.6rem;padding:.5rem .7rem;border:1px solid var(--mist-300);border-radius:.4rem}.source-strip{display:grid;grid-template-columns:repeat(auto-fit,minmax(15rem,1fr));gap:1rem;margin:1.2rem 0}.source-strip article{display:grid;gap:.45rem;padding:1rem;border-left:3px solid var(--amber-400);border-radius:.2rem .75rem .75rem .2rem;background:var(--paper)}.source-strip p,.source-strip small{margin:0;color:var(--ink-600)}.source-strip button{justify-self:start;margin-top:.3rem}.library-desk{display:grid;grid-template-columns:minmax(18rem,25rem) minmax(0,1fr);gap:1rem;align-items:start}.library-error{padding:.7rem;border-radius:.4rem;background:var(--water-100);color:var(--ink-800)}@media(max-width:760px){.library-header{align-items:stretch;flex-direction:column}.header-actions button{flex:1}.library-desk{display:block}.library-desk.is-mobile-detail :deep(.media-catalog){display:none}.library-desk:not(.is-mobile-detail) :deep(.inspector){display:none}}</style>
